mapper.sql:
a.type = #{query.type}
AND a.status = 1
AND a.publish_time IS NOT NULL

mapper.select:
SELECT 
FROM article a
LEFT JOIN category c ON c.id = a.category_id
WHERE a.type = #{query.type}

    AND a.status = #{query.status}


    AND a.category_id = #{query.categoryId}


    AND MATCH(a.title, a.summary) AGAINST(#{query.fullTextExpression} IN BOOLEAN MODE)


    AND a.title LIKE #{query.prefixExpression}

ORDER BY a.gmt_modified DESC
